/// <summary>
/// AVA/WEN/2025/05/21      AVA_013218_ProdSetupRelease
/// </summary>
internal final class AVACreateInventQualityOrderController  extends SysOperationServiceController
{
}

Method.Source:
public static AVACreateInventQualityOrderController construct(SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Synchronous)
{
    AVACreateInventQualityOrderController controller;
    controller = new AVACreateInventQualityOrderController();
    controller.parmExecutionMode(_executionMode);
    return controller;
}

public static void main(Args _args)
{
    AVACreateInventQualityOrderController controller;
    AVACreateInventQualityOrderContract contract;
    InventQualityOrderTable inventQOrder;
    ProdTable prodTable;

    controller = AVACreateInventQualityOrderController::construct();
    if (_args.record() && _args.dataset() == tableNum(InventQualityOrderTable))
    {
        inventQOrder = _args.record();
    }
    else
    {
        prodTable = _args.caller().args().record();
    }

    if (!prodTable)
    {
        if (inventQOrder.ReferenceType == InventTestReferenceType::Production || inventQOrder.ReferenceType == InventTestReferenceType::RouteOpr)
        {
            prodTable = prodTable::find(inventQOrder.InventRefId);
        }
    }

    if (!prodTable)
    {
        throw error(error::missingRecord(tableStr(ProdTable)));        
    }

    contract = controller.getDataContractObject();
    contract.parmProdId(prodTable.ProdId);
    controller.parmArgs(_args);
    controller.startOperation();
}

public boolean parmShowDialog(boolean _showDialog = showDialog)
{
    return false;
}
